import java.util.*;

class Solution {
  public List<String> validStrings(int n) {
    List<String> result = new ArrayList<>();
    char[] current = new char[n];
    build(0, true, current, result);
    return result;
  }

  private void build(int index, boolean canUseZero, char[] current, List<String> result) {
    if (index == current.length) {
      result.add(new String(current));
      return;
    }
    current[index] = '1';
    build(index + 1, true, current, result);
    if (canUseZero) {
      current[index] = '0';
      build(index + 1, false, current, result);
    }
  }
}
